// Bloom Filter — O(k) insert and lookup, O(m/8) bytes space
class BloomFilter {
  #bits;   // packed bit array: 1 byte holds 8 bits
  #m;      // total number of bits
  #k;      // number of hash functions

  constructor(m = 2048, k = 7) {
    this.#m    = m;
    this.#k    = k;
    // Uint8Array packs 8 bits per byte — 2048 bits = 256 bytes
    this.#bits = new Uint8Array(Math.ceil(m / 8));
  }

  // Derive k bit positions from two base hashes via double hashing:
  // g_i(x) = (h1(x) + i * h2(x)) mod m
  // This avoids computing k truly independent hash functions.
  #positions(item) {
    const s = String(item);
    // Two well-mixed 32-bit hashes in one pass (cyrb53-style multiply/xor mixing).
    // Weak, correlated hashes (e.g. two simple *31 / *37 polynomials) measurably
    // push the real false-positive rate above the formula.
    let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      h1 = Math.imul(h1 ^ c, 2654435761);
      h2 = Math.imul(h2 ^ c, 1597334677);
    }
    h1  = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
    h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2  = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
    h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    h1 = h1 >>> 0;            // unsigned 32-bit
    h2 = (h2 | 1) >>> 0;      // odd, so the step is never 0 (| yields signed — re-apply >>> 0)
    const pos = [];
    for (let i = 0; i < this.#k; i++) {
      pos.push((h1 + i * h2) % this.#m);   // < 2^37, exact in a JS number
    }
    return pos;
  }

  // Bit manipulation helpers — pos>>3 is the byte index, pos&7 is the bit offset
  #setBit(pos)  { this.#bits[pos >> 3] |=  (1 << (pos & 7)); }
  #testBit(pos) { return !!(this.#bits[pos >> 3] & (1 << (pos & 7))); }

  // O(k): set k bits
  add(item) {
    for (const pos of this.#positions(item)) this.#setBit(pos);
  }

  // O(k): check k bits
  // Returns false  → element DEFINITELY not present (100% guaranteed)
  // Returns true   → element PROBABLY present (may be false positive)
  mightContain(item) {
    return this.#positions(item).every(pos => this.#testBit(pos));
  }

  // Useful diagnostic: what fraction of bits are currently set?
  // Fill ratio above ~0.5 means the filter is past its design point and FPR is rising.
  get fillRatio() {
    let setBits = 0;
    for (const byte of this.#bits) {
      // Brian Kernighan's bit-count trick
      let b = byte;
      while (b) { setBits++; b &= b - 1; }
    }
    return setBits / this.#m;
  }

  get estimatedFPR() {
    // FPR ≈ fillRatio^k at the current fill level
    return Math.pow(this.fillRatio, this.#k);
  }
}

// --- Sizing helper: compute optimal m and k before construction ---
function bloomSize(n, targetFPR) {
  const ln2 = Math.LN2;
  const m   = Math.ceil(-n * Math.log(targetFPR) / (ln2 * ln2));
  const k   = Math.max(1, Math.round((m / n) * ln2));
  return { bits: m, hashes: k, bytes: Math.ceil(m / 8) };
}

console.log(bloomSize(1_000_000, 0.01));
// { bits: 9585059, hashes: 7, bytes: 1198133 }  ← ~1.2 MB for 1M elements at 1% FPR
console.log(bloomSize(1_000_000, 0.001));
// { bits: 14377588, hashes: 10, bytes: 1797199 } ← ~1.8 MB for 0.1% FPR

// --- Demo ---
const bf = new BloomFilter(2048, 7);
const words = ['apple', 'banana', 'cherry', 'date', 'elderberry'];
words.forEach(w => bf.add(w));

console.log(bf.mightContain('apple'));      // true  — inserted, definitely reported
console.log(bf.mightContain('cherry'));     // true  — inserted
console.log(bf.mightContain('mango'));      // false — never inserted, 100% correct
console.log(bf.mightContain('grape'));      // false — never inserted, 100% correct
console.log('fill ratio:', bf.fillRatio.toFixed(4));     // should be low
console.log('estimated FPR:', bf.estimatedFPR.toFixed(6)); // << 0.01

// Demonstrating false-positive rate vs fill ratio
// This shows the math matching reality

function runExperiment(m, k, n) {
  const filter = new BloomFilter(m, k);

  // Insert n unique strings
  for (let i = 0; i < n; i++) {
    filter.add(`inserted_item_${i}`);
  }

  // Test 10,000 strings that were NEVER inserted
  let falsePositives = 0;
  const testCount = 10_000;
  for (let i = 0; i < testCount; i++) {
    if (filter.mightContain(`never_inserted_${i}`)) falsePositives++;
  }

  const actualFPR   = falsePositives / testCount;
  const fillRatio   = filter.fillRatio;
  // Theoretical FPR at this fill level
  const theoreticalFPR = Math.pow(1 - Math.exp(-k * n / m), k);

  return { m, k, n, fillRatio: fillRatio.toFixed(3),
           actualFPR: actualFPR.toFixed(4), theoreticalFPR: theoreticalFPR.toFixed(4) };
}

// Optimal filter: m = 9.6*n bits, k = 7 hashes => target ~1% FPR
console.log(runExperiment(96_000, 7, 10_000));
// fillRatio ~0.52, actualFPR ~0.010, theoreticalFPR 0.0100

// Undersized filter: only 4 bits per element
console.log(runExperiment(40_000, 7, 10_000));
// fillRatio ~0.83, actualFPR ~0.26, theoreticalFPR 0.2628  — 26× worse!

// Too many hash functions: k=20 with the same m
console.log(runExperiment(96_000, 20, 10_000));
// fillRatio ~0.88, actualFPR ~0.07, theoreticalFPR 0.0700  — 7× worse

// Too few hash functions: k=2 with the same m
console.log(runExperiment(96_000, 2, 10_000));
// fillRatio ~0.19, actualFPR ~0.035, theoreticalFPR 0.0354 — 3.5× worse
